head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
        txb_ISU_CD.setValue(parentWin.txb_SearchIsuCd.getValue());
        txb_ISU_NM.setValue(parentWin.txb_SearchIsuNm.getValue());
        await scwin.readSync();
        if (dts_Item.getRowCount() === 0) {
            dts_Item.insertRow();
            btn_save.setBackgroundImage("../img/btn_save.gif");
            btn_save.setDisabled(false);
            btn_Update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_Update.setDisabled(true);
        } else {
            btn_save.setBackgroundImage("../img/btn_save_d.gif");
            btn_save.setDisabled(true);
            btn_Update.setBackgroundImage("../img/btn_modify.gif");
            btn_Update.setDisabled(false);
        }
        edt_EXPS_RTO.focus();

        // pIndex = getQuery(frame.srcUrl, "nIndex");
        // dts_Item.AddRow();
        // fn_initForm(pIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08013.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08013.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Update_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08013.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08013.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = function() {
    try {
        $c.lc.fn_alertMsg('S');
        btn_save.setBackgroundImage("../img/btn_save_d.gif");
        btn_save.setDisabled(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08013.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08013.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name txa_ETN_INVSTWARN_CONTN_OnKillFocus
 * @description txa_ETN_INVSTWARN_CONTN 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.txa_ETN_INVSTWARN_CONTN_OnKillFocus = function() {
    try {
        edt_EXPS_RTO.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08013.txa_ETN_INVSTWARN_CONTN_OnKillFocus" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // alert('trsIdx:'+trsIdx);
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnNewList.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/etn/EtnNewList.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_ISU_CD_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};

/**
 * @method
 * @name initForm
 * @description init Form 처리
 * @param {*} gubnVal gubnVal
 * @returns {void}
 * @hidden N
 */
scwin.initForm = function(gubnVal) {

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_EXPS_RTO.getValue() === "") {
        await $c.win.alert("[제비용]를 입력하세요.");
        edt_EXPS_RTO.focus();
        return false;
    }
    if (txb_HPAGE.getValue() === "") {
        await $c.win.alert("[홈페이지]를 입력하세요.");
        txb_HPAGE.focus();
        return false;
    }
    if (txa_ETN_PROD_INFO.getValue() === "") {
        await $c.win.alert("[상품정보(기본정보)]를 입력하세요.");
        txa_ETN_PROD_INFO.focus();
        return false;
    }
    if (txa_ETN_INVSTWARN_CONTN.getValue() === "") {
        await $c.win.alert("[상품정보(투자유의사항)]를 입력하세요.");
        txa_ETN_INVSTWARN_CONTN.focus();
        return false;
    }
    /*
    if (getObjectValue(txa_DISTR_PAY_BAS_DD_ENG_CONTN) == "")
    {
    	alert("[영문분배금 지급기준일]를 입력하세요.");txa_DISTR_PAY_BAS_DD_ENG_CONTN.focus();
    	return false;
    }
    if (getObjectValue(txa_ETN_ENG_PROD_INFO) == "")
    {
    	alert("[영문상품정보(기본정보)]를 입력하세요.");txa_ETN_ENG_PROD_INFO.focus();
    	return false;
    }
    if (getObjectValue(txa_ETN_ENG_INVSTWARN_CONTN) == "")
    {
    	alert("[영문상품정보(투자유의사항)]를 입력하세요.");txa_ETN_ENG_INVSTWARN_CONTN.focus();
    	return false;
    }
     */
    return true;
};

/**
 * @method
 * @name setValue
 * @description set Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.setValue = function() {
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Item.setCellData(1, "EXPS_RTO", edt_EXPS_RTO.getValue());
    dts_Item.setCellData(1, "HPAGE", txb_HPAGE.getValue());
    dts_Item.setCellData(1, "ETN_PROD_INFO", txa_ETN_PROD_INFO.getValue());
    dts_Item.setCellData(1, "ETN_INVSTWARN_CONTN", txa_ETN_INVSTWARN_CONTN.getValue());
    dts_Item.setCellData(1, "DISTR_PAY_BAS_DD_ENG_CONTN", txa_DISTR_PAY_BAS_DD_ENG_CONTN.getValue());
    dts_Item.setCellData(1, "ETN_ENG_PROD_INFO", txa_ETN_ENG_PROD_INFO.getValue());
    dts_Item.setCellData(1, "ETN_ENG_INVSTWARN_CONTN", txa_ETN_ENG_INVSTWARN_CONTN.getValue());
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        // dts_Item.UserStatus(1) = TB_JOB_INSERT;
        dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};
